import forge from"node-forge";let key,publicKey="",privateKey="";export function generateRSAKeyPair(){key=forge.pki.rsa.generateKeyPair(2048),publicKey=forge.pki.publicKeyToPem(key.publicKey),privateKey=forge.pki.privateKeyToPem(key.privateKey)}export function getPublicKey(){return publicKey}export function publicEncrypt(e){try{const r=forge.util.encodeUtf8(e),t=key.publicKey.encrypt(r,"RSA-OAEP",{md:forge.md.sha256.create(),mgf1:{md:forge.md.sha256.create()}});return forge.util.encode64(t)}catch(e){throw`加密失败：${e.message}`}}export function privateDecrypt(e){try{const r=forge.util.decode64(e),t=key.privateKey.decrypt(r,"RSA-OAEP",{md:forge.md.sha256.create(),mgf1:{md:forge.md.sha256.create()}});return forge.util.decodeUtf8(t)}catch(e){throw`解密失败：${e.message}`}}